export function renderCrossLevelSectionHtml(level, activeName = null, lang = 'ko', currentApp = 'myhome', maxLevel = 999) {
  const isKo = !lang || lang === 'ko';
  const lv = Math.max(0, Math.min(maxLevel, Math.floor(Number(level) || 0)));
  const prevLv = lv <= 0 ? maxLevel : lv - 1;
  const nextLv = lv >= maxLevel ? 0 : lv + 1;
  const randLv = (lv + 373) % (maxLevel + 1);
  const langSuffix = (!isKo && lang) ? `?lang=${encodeURIComponent(lang)}` : '';

  const prevLabel = isKo ? `◀ 이전 단계 (Lv.${prevLv})` : `◀ Previous (Lv.${prevLv})`;
  const randLabel = isKo ? `🎲 랜덤 단계 보기` : `🎲 Random Level`;
  const nextLabel = isKo ? `다음 단계 (Lv.${nextLv}) ▶` : `Next (Lv.${nextLv}) ▶`;

  const navBarHtml = `
    <nav class="level-step-nav" aria-label="${isKo ? '이전 및 다음 단계 이동' : 'Previous and Next Level Navigation'}" style="display:flex;gap:0.6rem;justify-content:space-between;align-items:center;margin:1.25rem 0;flex-wrap:wrap;">
      <a href="/level/${prevLv}${langSuffix}" class="step-nav-btn step-prev-btn" data-target-level="${prevLv}" style="flex:1;min-width:140px;text-align:center;padding:0.85rem 1rem;border-radius:12px;background:rgba(30,41,59,0.9);border:1px solid rgba(148,163,184,0.3);color:#f8fafc;text-decoration:none;font-weight:700;font-size:0.95rem;">
        ${esc(prevLabel)}
      </a>
      <a href="/level/${randLv}${langSuffix}" class="step-nav-btn step-rand-btn" data-target-level="${randLv}" style="padding:0.85rem 1.1rem;border-radius:12px;background:rgba(56,189,248,0.15);border:1px solid rgba(56,189,248,0.4);color:#38bdf8;text-decoration:none;font-weight:700;font-size:0.95rem;">
        ${esc(randLabel)}
      </a>
      <a href="/level/${nextLv}${langSuffix}" class="step-nav-btn step-next-btn" data-target-level="${nextLv}" style="flex:1;min-width:140px;text-align:center;padding:0.85rem 1rem;border-radius:12px;background:rgba(30,41,59,0.9);border:1px solid rgba(148,163,184,0.3);color:#f8fafc;text-decoration:none;font-weight:700;font-size:0.95rem;">
        ${esc(nextLabel)}
      </a>
    </nav>
  `;

  const targets = Object.keys(CROSS_MAP).filter(k => k !== currentApp);
  const cardsHtml = targets.map(appKey => {
    const meta = APP_META[appKey];
    const table = CROSS_MAP[appKey] || {};
    const targetLv = Math.min(lv, Object.keys(table).length - 1);
    const item = table[targetLv];
    if (!meta || !item) return '';

    const padded = String(targetLv).padStart(5, '0');
    const imgUrl = `${meta.r2Prefix}/${padded}.webp`;
    const levelUrl = `${meta.origin}/level/${targetLv}${langSuffix}`;
    const nameUrl = activeName
      ? `${meta.origin}/name/${encodeURIComponent(activeName)}${langSuffix}`
      : null;

    const heading = (isKo ? meta.koHeading : meta.enHeading).replace('{level}', targetLv);
    const title = isKo ? item.title : (item.enTitle || item.title);
    const era = isKo ? item.era : (item.enEra || item.era);
    const val = isKo ? item.value : (item.enValue || item.value);
    const feat = isKo ? item.feature : (item.enFeature || item.feature);
    const verdict = isKo ? item.verdict : '';
    const levelBtnText = (isKo ? meta.koLevelBtn : meta.enLevelBtn).replace('{level}', targetLv);
    const nameBtnText = activeName
      ? (isKo ? meta.koNameBtn : meta.enNameBtn).replace('{name}', activeName)
      : '';

    return `
      <article class="cross-level-card" data-cross-app="${esc(appKey)}" data-cross-level="${targetLv}" style="background:rgba(15,23,42,0.85);border:1px solid rgba(148,163,184,0.25);border-radius:16px;padding:1.25rem;display:flex;flex-direction:column;gap:0.9rem;">
        <header style="display:flex;align-items:center;justify-content:space-between;gap:0.5rem;flex-wrap:wrap;">
          <span style="font-size:0.85rem;font-weight:700;color:#38bdf8;">${meta.emoji} ${esc(heading)}</span>
          <span style="font-size:0.8rem;font-weight:700;padding:0.2rem 0.6rem;border-radius:999px;background:rgba(56,189,248,0.15);color:#7dd3fc;">Lv.${targetLv}</span>
        </header>
        <a href="${esc(levelUrl)}" style="text-decoration:none;color:inherit;display:flex;gap:1rem;align-items:flex-start;flex-wrap:wrap;">
          <img src="${esc(imgUrl)}" alt="Lv.${targetLv} ${esc(title)}" width="140" height="140" loading="lazy" style="width:120px;height:120px;object-fit:cover;border-radius:12px;border:1px solid rgba(148,163,184,0.2);flex-shrink:0;background:#1e293b;" />
          <div style="flex:1;min-width:200px;">
            <h3 style="font-size:1.1rem;font-weight:800;color:#f8fafc;margin:0 0 0.5rem 0;line-height:1.4;">${esc(title)}</h3>
            <p style="font-size:0.85rem;color:#94a3b8;margin:0 0 0.3rem 0;"><strong>${esc(isKo ? meta.koEraLabel : meta.enEraLabel)}:</strong> ${esc(era)}</p>
            <p style="font-size:0.85rem;color:#fbbf24;margin:0 0 0.45rem 0;"><strong>${esc(isKo ? meta.koValLabel : meta.enValLabel)}:</strong> ${esc(val)}</p>
            <p style="font-size:0.88rem;color:#cbd5e1;margin:0;line-height:1.55;">${esc(feat)}</p>
          </div>
        </a>
        ${verdict ? `<p style="font-size:0.85rem;color:#a5b4fc;background:rgba(30,41,59,0.7);padding:0.65rem 0.85rem;border-radius:10px;margin:0;line-height:1.5;">"${esc(verdict)}"</p>` : ''}
        <div style="display:flex;gap:0.6rem;flex-wrap:wrap;margin-top:auto;">
          <a href="${esc(levelUrl)}" style="flex:1;min-width:160px;text-align:center;padding:0.7rem 0.9rem;border-radius:10px;background:#0284c7;color:#fff;text-decoration:none;font-weight:700;font-size:0.88rem;">
            ${esc(levelBtnText)}
          </a>
          ${nameUrl ? `
          <a href="${esc(nameUrl)}" style="flex:1;min-width:180px;text-align:center;padding:0.7rem 0.9rem;border-radius:10px;background:rgba(245,158,11,0.18);border:1px solid rgba(245,158,11,0.5);color:#fde68a;text-decoration:none;font-weight:700;font-size:0.88rem;">
            ${esc(nameBtnText)}
          </a>` : ''}
        </div>
      </article>
    `;
  }).join('\n');

  const foodUrl = activeName
    ? `https://food.tellmyname.app/name/${encodeURIComponent(activeName)}${langSuffix}`
    : `https://food.tellmyname.app/${langSuffix}`;
  const foodBtnLabel = activeName
    ? (isKo ? `🍱 '${activeName}' 이름으로 오늘의 5끼 식단 추천받기 →` : `🍱 Get Today's 5 Meals for '${activeName}' →`)
    : (isKo ? `🍱 오늘 뭐 먹지? 하루 5끼 맞춤 식단 보러가기 →` : `🍱 Explore What to Eat Today (5 Daily Meals) →`);

  const sectionTitle = isKo
    ? `🔗 같은 레벨(Lv.${lv})의 다른 세계관에서는 어떨까?`
    : `🔗 What does Level ${lv} look like in our sibling worlds?`;
  const sectionSub = isKo
    ? `집·직업·자동차 세계관의 Lv.${lv} 결과를 한눈에 비교해 보세요. 카드를 누르면 해당 세계관의 Lv.${lv} 페이지로 이동합니다.`
    : `Compare Level ${lv} across Houses, Jobs, and Cars. Click any card to jump directly to Level ${lv} on that site.`;

  return `
    ${navBarHtml}
    <section class="cross-level-section" aria-label="${esc(sectionTitle)}" style="margin:1.5rem 0;padding:1.35rem;border-radius:18px;background:rgba(30,41,59,0.55);border:1px solid rgba(148,163,184,0.2);">
      <div style="margin-bottom:1rem;">
        <span style="display:inline-block;font-size:0.75rem;font-weight:800;letter-spacing:0.06em;color:#38bdf8;background:rgba(56,189,248,0.12);padding:0.2rem 0.6rem;border-radius:6px;margin-bottom:0.4rem;">CROSS-UNIVERSE LEVEL ${lv}</span>
        <h2 style="font-size:1.25rem;font-weight:800;color:#f8fafc;margin:0 0 0.3rem 0;">${esc(sectionTitle)}</h2>
        <p style="font-size:0.88rem;color:#94a3b8;margin:0;">${esc(sectionSub)}</p>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1rem;">
        ${cardsHtml}
      </div>
      <div style="margin-top:1rem;padding-top:0.9rem;border-top:1px solid rgba(148,163,184,0.15);display:flex;gap:0.6rem;flex-wrap:wrap;justify-content:space-between;align-items:center;">
        <a href="${esc(foodUrl)}" style="flex:1;min-width:220px;text-align:center;padding:0.75rem 1rem;border-radius:10px;background:rgba(16,185,129,0.15);border:1px solid rgba(16,185,129,0.4);color:#6ee7b7;text-decoration:none;font-weight:700;font-size:0.9rem;">
          ${esc(foodBtnLabel)}
        </a>
        <a href="https://tellmyname.app/${langSuffix}" style="padding:0.75rem 1rem;border-radius:10px;background:rgba(148,163,184,0.12);border:1px solid rgba(148,163,184,0.25);color:#cbd5e1;text-decoration:none;font-weight:700;font-size:0.88rem;">
          ✨ TellMyName 전체 서비스 허브
        </a>
        <a href="https://photodiary.tellmyname.app/${langSuffix}" style="padding:0.75rem 1rem;border-radius:10px;background:rgba(168,85,247,0.14);border:1px solid rgba(168,85,247,0.35);color:#d8b4fe;text-decoration:none;font-weight:700;font-size:0.88rem;">
          📸 포토 다이어리
        </a>
      </div>
    </section>
  `;
}
